import { Injectable, inject, Injector } from '@angular/core';
import { SupabaseClient } from '@supabase/supabase-js';
import { Database } from 'supabase/types/supabase';
import { AlertService } from '../common/alert/alert.service';
import { Tag, VerseTag } from '../common/verse/verse';

@Injectable({
  providedIn: 'root',
})
export class TagsService {
  private readonly alertService = inject(AlertService);
  private readonly supabase = inject<SupabaseClient<Database>>(SupabaseClient);
  private readonly injector = inject(Injector);

  /**
   * Trigger widget sync after data modifications.
   * Uses lazy injection to avoid circular dependencies.
   */
  private async triggerWidgetSync(): Promise<void> {
    // Lazy import to avoid circular dependencies
    const { FavoritesService } = await import('../favorites/favorites.service');
    const favoritesService = this.injector.get(FavoritesService);
    await favoritesService.syncToWidget();
  }

  /**
   * Get all tags for the current user
   */
  async getUserTags(): Promise<Tag[]> {
    try {
      const { data, error } = await this.supabase
        .from('tags')
        .select('*')
        .order('name', { ascending: true });

      if (error) {
        throw error;
      }

      return data as Tag[];
    } catch (error) {
      this.alertService.createNotice({
        message: 'Failed to fetch tags',
        duration: 5000,
        color: 'danger',
        positionAnchor: 'footer',
      });
      return [];
    }
  }

  /**
   * Get all tags for a specific verse
   */
  async getVerseTags(verseId: number): Promise<Tag[]> {
    try {
      const { data, error } = await this.supabase
        .from('verse_tags')
        .select('*, tags(*)')
        .eq('verse_id', verseId);

      if (error) {
        throw error;
      }

      // Extract the tag objects from the joined data
      return (data as (VerseTag & { tags: Tag })[]).map((vt) => vt.tags);
    } catch (error) {
      this.alertService.createNotice({
        message: 'Failed to fetch verse tags',
        duration: 5000,
        color: 'danger',
        positionAnchor: 'footer',
      });
      return [];
    }
  }

  /**
   * Create a new tag
   */
  async createTag(name: string, color?: string): Promise<Tag | null> {
    try {
      const insertData: { name: string; color?: string } = { name: name.trim() };
      if (color) {
        insertData.color = color;
      }

      const { data, error } = await this.supabase
        .from('tags')
        .insert(insertData)
        .select()
        .single();

      if (error) {
        // Handle unique constraint violation
        if (error.code === '23505') {
          throw new Error('A tag with this name already exists');
        }
        throw error;
      }

      // Sync widget data after creating a tag
      this.triggerWidgetSync();

      return data as Tag;
    } catch (error) {
      const message =
        error instanceof Error ? error.message : 'Failed to create tag';
      this.alertService.createNotice({
        message,
        duration: 5000,
        color: 'danger',
        positionAnchor: 'footer',
      });
      return null;
    }
  }

  /**
   * Add a tag to a verse. Also auto-favorites the verse if not already favorited.
   */
  async addTagToVerse(verseId: number, tagId: number): Promise<boolean> {
    try {
      // First, add the tag to the verse
      const { error: tagError } = await this.supabase
        .from('verse_tags')
        .insert({ verse_id: verseId, tag_id: tagId });

      if (tagError) {
        // Handle duplicate assignment
        if (tagError.code === '23505') {
          // Tag already assigned, not an error
          return true;
        }
        throw tagError;
      }

      // Auto-favorite the verse if not already favorited
      await this.supabase
        .from('verses')
        .update({ is_favorite: true })
        .eq('id', verseId)
        .eq('is_favorite', false); // Only update if not already favorited

      // Sync widget data after adding tag to verse
      this.triggerWidgetSync();

      return true;
    } catch (error) {
      this.alertService.createNotice({
        message: 'Failed to add tag to verse',
        duration: 5000,
        color: 'danger',
        positionAnchor: 'footer',
      });
      return false;
    }
  }

  /**
   * Remove a tag from a verse
   */
  async removeTagFromVerse(verseId: number, tagId: number): Promise<boolean> {
    try {
      const { error } = await this.supabase
        .from('verse_tags')
        .delete()
        .eq('verse_id', verseId)
        .eq('tag_id', tagId);

      if (error) {
        throw error;
      }

      // Sync widget data after removing tag from verse
      this.triggerWidgetSync();

      return true;
    } catch (error) {
      this.alertService.createNotice({
        message: 'Failed to remove tag from verse',
        duration: 5000,
        color: 'danger',
        positionAnchor: 'footer',
      });
      return false;
    }
  }

  /**
   * Delete a tag entirely (also removes all verse associations)
   */
  async deleteTag(tagId: number): Promise<boolean> {
    try {
      const { error } = await this.supabase
        .from('tags')
        .delete()
        .eq('id', tagId);

      if (error) {
        throw error;
      }

      // Sync widget data after deleting tag
      this.triggerWidgetSync();

      return true;
    } catch (error) {
      this.alertService.createNotice({
        message: 'Failed to delete tag',
        duration: 5000,
        color: 'danger',
        positionAnchor: 'footer',
      });
      return false;
    }
  }

  /**
   * Update a tag's name or color
   */
  async updateTag(
    tagId: number,
    updates: { name?: string; color?: string }
  ): Promise<Tag | null> {
    try {
      const { data, error } = await this.supabase
        .from('tags')
        .update(updates)
        .eq('id', tagId)
        .select()
        .single();

      if (error) {
        if (error.code === '23505') {
          throw new Error('A tag with this name already exists');
        }
        throw error;
      }

      // Sync widget data after updating tag
      this.triggerWidgetSync();

      return data as Tag;
    } catch (error) {
      const message =
        error instanceof Error ? error.message : 'Failed to update tag';
      this.alertService.createNotice({
        message,
        duration: 5000,
        color: 'danger',
        positionAnchor: 'footer',
      });
      return null;
    }
  }
}


